basic.code:
CREATE TABLE events (
  user_id text,
  ts timeuuid,
  event_type text,
  PRIMARY KEY (user_id, ts)
);

CREATE TABLE products (
  id uuid PRIMARY KEY,
  tags set<text>,
  attrs map<text, text>
);

INSERT INTO sessions (session_id, user_id)
VALUES (uuid(), 42)
USING TTL 3600;

UPDATE users
SET email = 'a@example.com'
WHERE user_id = 123;

intermediate.code:
CREATE TABLE events_by_user (
  user_id text,
  created_at timeuuid,
  event text,
  PRIMARY KEY (user_id, created_at)
) WITH CLUSTERING ORDER BY (created_at DESC);

